// Exnoria - ret.account.flag
// Build churn risk summary and determine urgency

const webhook = $("Webhook").first().json.body;
const contact = $input.first().json;

const { contact_id, account_id, signal_id, signal_severity } = webhook;

const firstname = contact.properties?.firstname?.value ?? 'Contact';
const lastname  = contact.properties?.lastname?.value  ?? '';
const email     = contact.properties?.email?.value     ?? '';
const company   = contact.properties?.company?.value   ?? '';

// Determine risk level from severity
let risk_level = 'low';
if (signal_severity > 0.8) risk_level = 'critical';
else if (signal_severity > 0.6) risk_level = 'high';
else if (signal_severity > 0.4) risk_level = 'medium';

const flaggedAt = new Date(new Date().setUTCHours(0,0,0,0)).getTime();

const summary = [
  '[CHURN RISK] ' + firstname + ' ' + lastname + ' - ' + company,
  'Account: ' + (account_id || 'N/A'),
  'Signal: ' + signal_id + ' (severity: ' + signal_severity + ')',
  'Risk level: ' + risk_level,
  'Email: ' + email,
  'Contact ID: ' + contact_id,
  '',
  'Action required: CSM review within ' + (risk_level === 'critical' ? '4 hours' : risk_level === 'high' ? '24 hours' : '48 hours')
].join('\n');

return [{
  json: {
    contact_id,
    account_id: account_id || 'N/A',
    signal_id,
    signal_severity,
    email,
    firstname,
    lastname,
    company,
    risk_level,
    flagged_at: flaggedAt,
    summary,
    flagged: true
  }
}];

